syntax.mysql:
DELETE FROM customers
WHERE customer_id IN (
  SELECT customer_id FROM (
    SELECT customer_id,
           ROW_NUMBER() OVER (PARTITION BY LOWER(TRIM(email))
                              ORDER BY signup_date, customer_id) AS rn
    FROM customers
  ) AS d
  WHERE d.rn > 1
);

